from pathlib import Path
import sys

repo = Path(sys.argv[1]) if len(sys.argv) > 1 else Path('.')
index_path = repo / '03-enterprise/prototype-v4/index.html'
styles_path = repo / '03-enterprise/prototype-v4/styles.css'
readme_path = repo / '03-enterprise/prototype-v4/README.md'

html = index_path.read_text()
css = styles_path.read_text()


def insert_before(marker: str, block: str, label: str):
    global html
    if block.strip() in html:
        return
    if marker not in html:
        raise SystemExit(f'missing marker for {label}: {marker[:100]}')
    html = html.replace(marker, block + marker, 1)


def replace_once(old: str, new: str, label: str):
    global html
    if new in html:
        return
    if old not in html:
        raise SystemExit(f'missing source for {label}: {old[:100]}')
    html = html.replace(old, new, 1)

